 "content": "def transform(grid):
    g=[r[:] for r in grid]; h,w=len(g),len(g[0])
    sep=next(v for v in set(v for row in g for v in row) if v and any(all(x==v for x in row) for row in g))
    yr=[i for i,row in enumerate(g) if all(x==sep for x in row)]
    xc=[j for j in range(w) if all(g[i][j]==sep for i in range(h))]
    ys=[(p+1,q) for p,q in zip([-1]+yr,yr+[h])]
    xs=[(p+1,q) for p,q in zip([-1]+xc,xc+[w])]
    # Each band has a 2x2 key in panel 0. The distinctive template determines
    # a repeating 4x4 bitmap, with motif cells located relative to the 4x4 tile.
    key=[]
    for a,b in ys:
      l,r=xs[0]
      c=next((g[i][j] for i in range(a,b) for j in range(l,r) if g[i][j] not in (0,sep)),None)
      key.append(c)
    # Ignore the key panel; template is the densest off-key region.
    cand=[]
    for a,b in ys:
      for l,r in xs[1:]:
        pts={(i-a,j-l) for i in range(a,b) for j in range(l,r) if g[i][j] not in (0,sep)}
        if pts: cand.append((len(pts),pts))
    pattern=max(cand,key=lambda x:x[0])[1]
    for ri,(a,b) in enumerate(ys):
      if key[ri] is None: continue
      color=key[ri]
      for l,r in xs:
        for di,dj in pattern:
          if di<b-a and dj<r-l: g[a+di][l+dj]=color
    return g
