 "content": "def transform(grid):
    g=[r[:] for r in grid]; h,w=len(g),len(g[0])
    sep=next(v for v in set(v for row in g for v in row) if v and any(all(x==v for x in row) for row in g))
    yr=[i for i,row in enumerate(g) if all(x==sep for x in row)]
    xc=[j for j in range(w) if all(g[i][j]==sep for i in range(h))]
    ys=[(p+1,q) for p,q in zip([-1]+yr,yr+[h])]
    xs=[(p+1,q) for p,q in zip([-1]+xc,xc+[w])]
    # Recover each 4x4 block's pattern from the key panel: ordinary bands use
    # the 2x2 color square; the band containing the multicolor stamp uses its
    # occupied cells as the bitmap. Repeat the same bitmap in every panel.
    for a,b in ys:
      kl,kr=xs[0]
      keycells=[(i-a,j-kl,g[i][j]) for i in range(a,b) for j in range(kl,kr) if g[i][j] not in (0,sep)]
      if not keycells: continue
      color=keycells[0][2]
      pattern={(dr,dc) for dr,dc,_ in keycells}
      # If an unusual non-key stamp occupies a panel, use its pattern instead.
      stamp=[]
      for l,r in xs[1:]:
        pts={(i-a,j-l) for i in range(a,b) for j in range(l,r) if g[i][j] not in (0,sep)}
        if len(pts)>len(pattern): stamp.append(pts)
      if stamp: pattern=max(stamp,key=len)
      for l,r in xs:
        for dr,dc in pattern:
          if a+dr<b and l+dc<r: g[a+dr][l+dc]=color
    return g
